from decimal import Decimal, ROUND_HALF_UP


def text(value):
    """Anything a source or an extractor gives us, as a comparable string."""
    return "" if value is None else str(value).strip()


def empty(value):
    return text(value) == ""


def amount(value):
    """An amount as a Decimal, or None when it is empty or unusable. OCR may give a
    comma or a dot as decimal separator, and thousands separators may appear."""
    s = text(value).replace(" ", "").replace("\u00a0", "")
    if s == "":
        return None
    if "," in s and "." in s:
        if s.rfind(",") > s.rfind("."):
            s = s.replace(".", "").replace(",", ".")
        else:
            s = s.replace(",", "")
    elif "," in s:
        s = s.replace(",", ".")
    try:
        return Decimal(s)
    except Exception:
        return None


def cents(value):
    d = amount(value)
    if d is None:
        return None
    return int((d * 100).quantize(Decimal("1"), rounding=ROUND_HALF_UP))


def fires(reason):
    return {"fires": True, "reason": reason}


def passes():
    return {"fires": False, "reason": ""}


LIMIT_CENTS = 1000000  # 10,000 EUR


def evaluate(instance, sources, others):
    """The invoice's total is not above 10,000 EUR; above that a person must review it."""
    total = cents(instance.get("total"))
    if total is None:
        return passes()
    if total > LIMIT_CENTS:
        return fires("TOTAL_ABOVE_10000")
    return passes()

